package com.printflow.identity;
import java.util.*;import java.util.regex.*;
/** Email-client-friendly layout. All dynamic content is escaped; links are limited to this application's origin. */
final class MailPresentation {
 static String reference(String reference){return "PF-"+reference.replace("-", "").substring(0,Math.min(8,reference.replace("-", "").length())).toUpperCase(Locale.ROOT);}
 static String phase(String kind){return Set.of("ENQUIRY","NEW_ENQUIRY","INTAKE","INVITE","REJECTION").contains(kind)?"INTAKE":"WORK";}
 static String subject(String kind,String reference,String product){if(reference==null)return title(kind)+" | J.D.Printex";String clean=(product==null?"Print project":product).replaceAll("[\\p{Cntrl}]"," ").strip();clean=switch(clean){case "Shaadi & Wedding Cards"->"Wedding Cards";default->clean;};return (phase(kind).equals("INTAKE")?"Enquiry received — ":"Your print order — ")+clean.substring(0,Math.min(80,clean.length()))+" · "+reference(reference)+" | J.D.Printex";}
 static String title(String kind){return switch(kind){case "DESIGN_ASSIGN"->"Your designer is assigned";case "PRODUCTION_UPDATE"->"Production progress update";case "DELIVERY_PHOTO"->"Delivery evidence update";case "PAYMENT_REQUEST"->"Your payment schedule";case "PAYMENT_RECEIVED"->"Payment received";case "PAYMENT_CORRECTED"->"Payment record corrected";case "INVOICE"->"Your invoice is ready";case "MESSAGE"->"New project message";case "REFERENCE_REVIEW"->"Artwork review requested";case "ENQUIRY"->"Your enquiry has been received";case "INVITE"->"Your customer account access";case "VERIFY"->"Verify your email address";case "RESET"->"Reset your password";case "INTAKE"->"Your enquiry has been accepted";case "QUOTE"->"Your quotation is ready";case "QUOTE_ACCEPT"->"Quotation accepted";case "QUOTE_CHANGE"->"Quotation changes requested";case "ARTWORK"->"Please share your artwork";case "REVIEW"->"Your artwork is ready for review";case "COMMENT"->"New artwork feedback";case "PROOF_CHANGE"->"Artwork changes requested";case "PROOF_OK"->"Artwork proof approved";case "PRODUCTION"->"Production has started";case "READY"->"Your print order is ready for dispatch";case "TRANSIT"->"Your print order is on its way";case "DELIVERED"->"Your print order has been delivered";case "COMPLETED"->"Your print order is complete";case "REJECTION"->"An update on your enquiry";case "NEW_ENQUIRY"->"New printing enquiry";default->"An update from J.D.Printex";};}
 static String escape(String value){return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static String paragraph(String text,String base){var matcher=Pattern.compile("https?://[^\\s]+").matcher(text);StringBuilder result=new StringBuilder();int end=0;while(matcher.find()){result.append(escape(text.substring(end,matcher.start())));String url=matcher.group();if(url.startsWith(base+"/")&&!url.contains("\"")&&!url.contains("<"))result.append("<a style=\"color:#247c78;word-break:break-all\" href=\"").append(escape(url)).append("\">").append(escape(url)).append("</a>");else result.append(escape(url));end=matcher.end();}return result.append(escape(text.substring(end))).toString().replace("\n","<br>");}
 static String html(String kind,String body,String base,String summary){return html(kind,body,base,summary,false);}
 static String html(String kind,String body,String base,String summary,boolean team){StringBuilder content=new StringBuilder();for(String part:body.split("\n\n")){if(part.equals("J.D.Printex"))continue;if(part.matches("Enquiry reference: [a-fA-F0-9-]{36}"))part="Print request "+reference(part.substring("Enquiry reference: ".length()));content.append("<p style=\"margin:0 0 18px;line-height:1.65;color:#29464a\">").append(paragraph(part,base)).append("</p>");}
  return "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head><body style=\"margin:0;background:#f4f6f3;font-family:Arial,Helvetica,sans-serif\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\"><tr><td align=\"center\" style=\"padding:28px 12px\"><table role=\"presentation\" width=\"600\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:100%;max-width:600px;background:white;border:1px solid #dfe7e3;border-radius:14px;overflow:hidden\"><tr><td style=\"padding:24px 30px;background:#153b40;color:white;font-size:24px;font-weight:bold\">J.D.Printex<span style=\"display:block;font-size:12px;font-weight:normal;color:#c6e2db;padding-top:8px\">Your print workspace</span></td></tr><tr><td style=\"padding:30px\"><h1 style=\"font-size:24px;line-height:1.3;color:#153b40;margin:0 0 22px\">"+escape(title(kind))+"</h1>"+(summary==null?"":"<div style=\"background:#edf5f0;border:1px solid #d9e8df;border-radius:8px;padding:18px;margin-bottom:24px;line-height:1.7;color:#153b40\"><strong>"+escape(summary).replace("\n","<br>")+"</strong><br>The quotation PDF is attached. Open your workspace for its current status.</div>")+content+"<p style=\"margin:26px 0\"><a href=\""+escape(base+(team?"/business":"/customer"))+"\" style=\"display:inline-block;padding:14px 22px;background:#153b40;border-radius:7px;color:white;text-decoration:none;font-weight:bold\" >"+(team?"Open team workspace":"Open customer workspace")+"</a></p><p style=\"font-size:13px;line-height:1.6;color:#63777b\">"+(team?"Sign in with your staff account to review the enquiry, artwork and project conversation.":"Sign in with the email used for your enquiry to review your quotation, artwork and order progress.")+"</p></td></tr><tr><td style=\"padding:20px 30px;background:#f7f9f7;font-size:12px;line-height:1.6;color:#63777b\">J.D.Printex · Printing made personal<br>Questions about this order? Reply to this email.</td></tr></table></td></tr></table></body></html>";
 }
}
